import sys

def match(filename, pattern):
    if len(filename) != len(pattern):
        return False
    for f_char, p_char in zip(filename, pattern):
        if p_char != '?' and f_char != p_char:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    filenames = input[2:2+n]
    indices = list(map(int, input[2+n:]))
    filenames_to_delete = [filenames[i-1] for i in indices]

    pattern = ['?'] * len(filenames_to_delete[0])
    for i in range(len(filenames_to_delete[0])):
        char = filenames_to_delete[0][i]
        if all(f[i] == char for f in filenames_to_delete):
            pattern[i] = char

    for f in filenames:
        if f not in filenames_to_delete and match(f, ''.join(pattern)):
            print("No")
            return

    print("Yes")
    print(''.join(pattern))

main()
